static ssize_t iwl_dbgfs_reset_write(struct file *file,
				     const char __user *user_buf,
				     size_t count, loff_t *ppos)
{
	struct iwl_trans *trans = file->private_data;
	static const char * const modes[] = {
		[IWL_RESET_MODE_SW_RESET] = "sw",
		[IWL_RESET_MODE_REPROBE] = "reprobe",
		[IWL_RESET_MODE_TOP_RESET] = "top",
		[IWL_RESET_MODE_REMOVE_ONLY] = "remove",
		[IWL_RESET_MODE_RESCAN] = "rescan",
		[IWL_RESET_MODE_FUNC_RESET] = "function",
		[IWL_RESET_MODE_PROD_RESET] = "product",
	};
	char buf[10] = {};
	int mode;

	if (count > sizeof(buf) - 1)
		return -EINVAL;

	if (copy_from_user(buf, user_buf, count))
		return -EFAULT;

	mode = sysfs_match_string(modes, buf);
	if (mode < 0)
		return mode;

	if (mode < IWL_RESET_MODE_REMOVE_ONLY) {
		if (!test_bit(STATUS_DEVICE_ENABLED, &trans->status))
			return -EINVAL;
		if (mode == IWL_RESET_MODE_TOP_RESET) {
			if (!iwl_trans_is_top_reset_supported(trans))
				return -EINVAL;
			trans->request_top_reset = 1;
		}
		iwl_trans_fw_error(trans, IWL_ERR_TYPE_DEBUGFS);
		return count;
	}

	iwl_trans_pcie_reset(trans, mode);

	return count;
}

static ssize_t lbs_sleepparams_write(struct file *file,
				const char __user *user_buf, size_t count,
				loff_t *ppos)
{
	struct lbs_private *priv = file->private_data;
	ssize_t ret;
	struct sleep_params sp;
	int p1, p2, p3, p4, p5, p6;
	char *buf;

	buf = memdup_user_nul(user_buf, min(count, len - 1));
	if (IS_ERR(buf))
		return PTR_ERR(buf);

	ret = sscanf(buf, "%d %d %d %d %d %d", &p1, &p2, &p3, &p4, &p5, &p6);
	if (ret != 6) {
		ret = -EINVAL;
		goto out_unlock;
	}
	sp.sp_error = p1;
	sp.sp_offset = p2;
	sp.sp_stabletime = p3;
	sp.sp_calcontrol = p4;
	sp.sp_extsleepclk = p5;
	sp.sp_reserved = p6;

	ret = lbs_cmd_802_11_sleep_params(priv, CMD_ACT_SET, &sp);
	if (!ret)
		ret = count;
	else if (ret > 0)
		ret = -EINVAL;

out_unlock:
	kfree(buf);
	return ret;
}

static ssize_t lbs_host_sleep_write(struct file *file,
				const char __user *user_buf, size_t count,
				loff_t *ppos)
{
	struct lbs_private *priv = file->private_data;
	ssize_t ret;
	int host_sleep;
	char *buf;

	buf = memdup_user_nul(user_buf, min(count, len - 1));
	if (IS_ERR(buf))
		return PTR_ERR(buf);

	ret = sscanf(buf, "%d", &host_sleep);
	if (ret != 1) {
		ret = -EINVAL;
		goto out_unlock;
	}

	if (host_sleep == 0)
		ret = lbs_set_host_sleep(priv, 0);
	else if (host_sleep == 1) {
		if (priv->wol_criteria == EHS_REMOVE_WAKEUP) {
			netdev_info(priv->dev,
				    "wake parameters not configured\n");
			ret = -EINVAL;
			goto out_unlock;
		}
		ret = lbs_set_host_sleep(priv, 1);
	} else {
		netdev_err(priv->dev, "invalid option\n");
		ret = -EINVAL;
	}

	if (!ret)
		ret = count;

out_unlock:
	kfree(buf);
	return ret;
}

static ssize_t lbs_threshold_write(uint16_t tlv_type, uint16_t event_mask,
				   struct file *file,
				   const char __user *userbuf, size_t count,
				   loff_t *ppos)
{
	struct cmd_ds_802_11_subscribe_event *events;
	struct mrvl_ie_thresholds *tlv;
	struct lbs_private *priv = file->private_data;
	int value, freq, new_mask;
	uint16_t curr_mask;
	char *buf;
	int ret;

	buf = memdup_user_nul(userbuf, min(count, len - 1));
	if (IS_ERR(buf))
		return PTR_ERR(buf);

	ret = sscanf(buf, "%d %d %d", &value, &freq, &new_mask);
	if (ret != 3) {
		ret = -EINVAL;
		goto out_page;
	}
	events = kzalloc_obj(*events);
	if (!events) {
		ret = -ENOMEM;
		goto out_page;
	}

	events->hdr.size = cpu_to_le16(sizeof(*events));
	events->action = cpu_to_le16(CMD_ACT_GET);

	ret = lbs_cmd_with_response(priv, CMD_802_11_SUBSCRIBE_EVENT, events);
	if (ret)
		goto out_events;

	curr_mask = le16_to_cpu(events->events);

	if (new_mask)
		new_mask = curr_mask | event_mask;
	else
		new_mask = curr_mask & ~event_mask;

	/* Now everything is set and we can send stuff down to the firmware */

	tlv = (void *)events->tlv;

	events->action = cpu_to_le16(CMD_ACT_SET);
	events->events = cpu_to_le16(new_mask);
	tlv->header.type = cpu_to_le16(tlv_type);
	tlv->header.len = cpu_to_le16(sizeof(*tlv) - sizeof(tlv->header));
	tlv->value = value;
	if (tlv_type != TLV_TYPE_BCNMISS)
		tlv->freq = freq;

	/* The command header, the action, the event mask, and one TLV */
	events->hdr.size = cpu_to_le16(sizeof(events->hdr) + 4 + sizeof(*tlv));

	ret = lbs_cmd_with_response(priv, CMD_802_11_SUBSCRIBE_EVENT, events);

	if (!ret)
		ret = count;
 out_events:
	kfree(events);
 out_page:
	kfree(buf);
	return ret;
}

