rtw89_debug_priv_disable_dm_set(struct rtw89_dev *rtwdev,
				struct rtw89_debugfs_priv *debugfs_priv,
				const char *buf, size_t count)
{
	u32 conf;
	int ret;

	ret = kstrtou32(buf, 0, &conf);
	if (ret)
		return -EINVAL;

	rtw89_core_dm_disable_cfg(rtwdev, conf);

	return count;
}

rtw89_debug_priv_static_pd_th_set(struct rtw89_dev *rtwdev,
				  struct rtw89_debugfs_priv *debugfs_priv,
				  const char *buf, size_t count)
{
	struct rtw89_hal *hal = &rtwdev->hal;
	int ret;
	u32 mode;
	s32 pd_th_dbm;

	ret = sscanf(buf, "%u %d", &mode, &pd_th_dbm);
	if (ret < 1)
		return -EINVAL;

	if (mode > 1)
		return -EINVAL;

	if (mode == 0) {
		rtw89_core_dm_disable_clr(rtwdev, RTW89_DM_DIG_PD);
		hal->fixed_dig_pd_th = 0;
		hal->fixed_dig_cck_pd_th = 0;

		rtw89_debug(rtwdev, RTW89_DBG_DIG,
			    "DIG static mode disabled\n");
	} else {
		if (ret < 2 || pd_th_dbm < RTW89_DIG_PD_TH_MIN_DBM ||
		    pd_th_dbm > RTW89_DIG_PD_TH_MAX_DBM)
			return -EINVAL;

		rtw89_core_dm_disable_set(rtwdev, RTW89_DM_DIG_PD);
		hal->fixed_dig_pd_th = clamp(rtw89_dig_pd_th_dbm_to_reg(pd_th_dbm),
					     0, 0x1f);
		/* CCK uses dBm directly */
		hal->fixed_dig_cck_pd_th = pd_th_dbm;

		rtw89_debug(rtwdev, RTW89_DBG_DIG,
			    "DIG static mode: PD=0x%02x (%d dBm), CCK=%d dBm\n",
			    hal->fixed_dig_pd_th,
			    rtw89_dig_pd_th_to_dbm(hal->fixed_dig_pd_th),
			    hal->fixed_dig_cck_pd_th);
	}

	return count;
}

rtw89_debug_priv_mlo_mode_set(struct rtw89_dev *rtwdev,
			      struct rtw89_debugfs_priv *debugfs_priv,
			      const char *buf, size_t count)
{
	u8 num, mlo_mode;
	u32 argv;

	num = sscanf(buf, "%hhx %u", &mlo_mode, &argv);
	if (num != 2)
		return -EINVAL;

	rtw89_core_dm_disable_set(rtwdev, RTW89_DM_MLO);

	rtw89_debug(rtwdev, RTW89_DBG_STATE, "Set MLO mode to %x\n", mlo_mode);

	switch (mlo_mode) {
	case RTW89_MLO_MODE_MLSR:
		rtw89_debug_mlo_mode_set_mlsr(rtwdev, argv);
		break;
	default:
		rtw89_debug(rtwdev, RTW89_DBG_STATE, "Unsupported MLO mode\n");
		rtw89_core_dm_disable_clr(rtwdev, RTW89_DM_MLO);

		return -EOPNOTSUPP;
	}

	return count;
}

rtw89_debug_priv_monitor_opts_set(struct rtw89_dev *rtwdev,
