	if (copy_from_user(&v, sel, sizeof(*sel)))
		return -EFAULT;

	/*
	 * TIOCL_SELCLEAR and TIOCL_SELPOINTER are OK to use without
	 * CAP_SYS_ADMIN as they do not modify the selection.
	 */
	switch (v.sel_mode) {
	case TIOCL_SELCLEAR:
	case TIOCL_SELPOINTER:
		break;
